// The bridge between the vendored database's colours and the app's palette.
//
// The database (src/shared/notion-database-sys, a submodule we do not edit)
// styles itself with 259 --color-* custom properties whose values are mostly
// literals, so its tables and charts ignore the palette. This module reads the
// stylesheet the app loads, and writes src/app/styles/database-bridge.generated.css:
// every one of those names, redefined as a reference to an app token.
//
// Mapping is by ROLE (a surface, a line, an ink, a tint family), through the
// table below. A name the table does not know is reported and fails the build,
// so a vendored update cannot put a colour outside the palette unnoticed.
//
// Ponytail: a role has ONE mapping for both modes, where the vendored theme
// tunes alpha per mode (its dark "-surface" tints are 8% washes, ours are the
// palette's own dark tint). Tints with no counterpart are folded into the
// nearest family (cyan and indigo into blue, amber into yellow, teal into
// green, rose into red), so two vendored hues can render the same.
// Literal colours the vendored markup writes inline, or as stock Tailwind
// classes, are out of reach of any variable and stay as they are.

export const VENDORED_THEME = "src/shared/notion-database-sys/src/theme.css";
export const BRIDGE_STYLESHEET = "src/app/styles/database-bridge.generated.css";

const HEADER = `/* GENERATED by scripts/build-tokens.mjs (scripts/tokens/databaseBridge.mjs) from
   the vendored database theme. Do not edit: run \`npm run tokens\` to regenerate. */`;

// Where the variables must exist: the page root (portalled menus and popovers
// render under <body>, outside the database), and the database's own roots.
// The vendored theme writes the same names on :root[data-theme=...] and on
// [data-theme=...] .notion-object-database, both at (0,2,0), and on
// [data-dbms-source][data-theme] at (0,2,0). These are (0,2,1): the type
// selector wins whatever the load order.
const BRIDGE_SELECTORS = ["html:root[data-theme]", "html[data-theme] .notion-object-database", "html[data-theme] [data-dbms-source]"];

const TINT = (colour, part) => `block-tint-${colour}-${part}`;

// vendored family -> [palette tint, status token or null]. The status tokens
// are solid colours; the tints are the palette's wash and ink.
const FAMILIES = {
  danger: ["red", "danger"], success: ["green", "success"], warning: ["yellow", "warning"],
  amber: ["yellow"], orange: ["orange"], purple: ["purple"], violet: ["purple"], indigo: ["blue"],
  pink: ["pink"], rose: ["red"], cyan: ["blue"], teal: ["green"], emerald: ["green"],
};
const GRADIENT_CARDS = { blue: "blue", "purple-card": "purple", green: "green", orange: "orange", pink: "pink", cyan: "blue" };

function familyLines(family, [colour, status]) {
  const ink = status ?? TINT(colour, "fg");
  const wash = TINT(colour, "bg");
  const toward = (pct) => `${wash}+${TINT(colour, "fg")} ${pct}`;
  const names = (suffixes) => suffixes.map((suffix) => `${family}${suffix}`).join(" ");
  return [
    `${ink}: ${names(["", "-vivid", "-bold", "-text", "-text-bold", "-text-tag", "-text-soft", "-text-faint"])}`,
    `${wash}: ${names(["-surface", "-surface2"])}`,
    `${wash} 50: ${family}-surface-soft`,
    `${toward(10)}: ${family}-surface-muted`,
    `${toward(18)}: ${family}-surface-medium`,
    `${toward(28)}: ${family}-surface-strong`,
    `${TINT(colour, "fg")} 30: ${family}-border`,
  ];
}

const cardLines = ([card, colour]) => [
  `${TINT(colour, "bg")}+${TINT(colour, "fg")} 8: gradient-${card}-from`,
  `${TINT(colour, "bg")}: gradient-${card}-to`,
];

// "token [alpha]: names" maps those names to the token, at that alpha;
// "token+other pct: names" mixes the token toward `other`.
const ROLES = `
bg-page: surface-primary gradient-surface-to
bg-subtle: surface-secondary hover-surface focus-surface gradient-surface-from
bg-muted: surface-tertiary hover-surface3 chart-fill
bg-hover: surface-muted hover-surface2
bg-surface: hover-surface-white
bg-surface 80: hover-surface-white-soft
bg-surface 60: hover-surface-white-soft2
bg-surface 50: hover-surface-white-soft3
border-default: surface-strong line-medium ring-neutral hover-border outline-inactive
border-strong: line-strong hover-border-strong
fg-strong: surface-inverse ink-strong hover-text-bolder hover-text-boldest
fg-default: surface-inverse-soft hover-surface-inverse ink ink-body fill-primary fill-body hover-text-strong focus-text chart-axis
fg-muted: ink-body-light ink-secondary ink-muted hover-text hover-text-muted chart-label
fg-subtle: ink-faint hover-text-faint placeholder fill-secondary chart-tick slate
fg-subtle 60: ink-disabled
fg-inverse: ink-inverse
db-line: line chart-grid
db-line-soft: line-light line-faint
bg-elevated 95: overlay
bg-elevated 82: overlay-medium
bg-elevated 62: overlay-light
overlay: scrim
overlay 85: scrim-medium
overlay 70: scrim-light
overlay 30: toggle-shadow
overlay 80: marker-shadow
bg-page 80: gradient-fade-from
bg-page 0: gradient-fade-to
bg-subtle 30: surface-secondary-soft5
bg-subtle 40: surface-secondary-soft4
bg-subtle 50: surface-secondary-soft hover-surface-soft
bg-subtle 60: surface-secondary-soft3
bg-subtle 80: surface-secondary-soft2
bg-muted 50: surface-tertiary-soft4
bg-muted 60: surface-tertiary-soft3 hover-surface-soft3
bg-muted 70: surface-tertiary-soft hover-surface-soft2
bg-muted 80: surface-tertiary-soft2 hover-surface-soft4
bg-hover 60: surface-muted-soft3
bg-hover 70: surface-muted-soft2
bg-hover 80: surface-muted-soft
accent: accent accent-border hover-accent focus-border-strong ring-accent-strong toggle-on outline-active gradient-accent-from gradient-brand-from gradient-purple-to progress-mid
accent-hover: accent-bold accent-bolder accent-text-bold accent-text-bolder hover-accent-bold hover-accent-text-bold hover-accent-text-bolder gradient-accent-to
accent-text: accent-text accent-text-light hover-accent-text
accent 5: accent-soft5
accent 6: accent-soft4 hover-surface-accent3
accent 8: accent-soft2 accent-soft3 hover-surface-accent
accent 10: accent-soft hover-accent-soft focus-surface-accent
accent 12: hover-surface-accent2
accent 14: accent-muted2
accent 16: accent-muted hover-accent-muted
accent 24: accent-subtle2
accent 28: accent-subtle accent-border-muted hover-border-accent
accent 42: accent-moderate hover-accent-moderate
accent 45: accent-border-soft
accent 60: accent-vivid
accent 65: accent-text-faint
accent 70: accent-border-light
accent 85: accent-text-soft hover-accent-subtle
focus-ring-color 70: focus-border ring-accent focus-ring-solid
focus-ring-color 45: focus-border-soft ring-accent-muted
focus-ring-color 30: focus-ring ring-accent-soft
focus-ring-color 28: focus-ring-muted ring-accent-faint
block-tint-red-bg: hover-danger
danger: hover-danger-text hover-danger-text-bold progress-critical
success: progress-high
success 80: ring-success
success 50: ring-success-soft inset-success
warning: progress-low
block-tint-purple-fg: gradient-brand-to gradient-violet-from gradient-violet2-from gradient-violet2-to gradient-purple-from
block-tint-blue-fg: gradient-violet-to
`;

const CHART_NAMES = Array.from({ length: 10 }, (_, i) => `chart-${i + 1}`);

const ROLE_LINES = [
  ...ROLES.trim().split("\n"),
  ...Object.entries(FAMILIES).flatMap(([family, spec]) => familyLines(family, spec)),
  ...Object.entries(GRADIENT_CARDS).flatMap(cardLines),
  ...CHART_NAMES.map((name) => `${name}: ${name}`),
];

function cssValue(target) {
  const [spec, pct] = target.split(" ");
  const [token, other] = spec.split("+");
  if (other) return `color-mix(in srgb, var(--osio-${token}), var(--osio-${other}) ${pct}%)`;
  if (pct === undefined) return `var(--osio-${token})`;
  return `color-mix(in srgb, var(--osio-${token}) ${pct}%, transparent)`;
}

/** vendored name (without the --color- prefix) -> CSS value. */
export function buildMapping(lines = ROLE_LINES) {
  const mapping = new Map();
  for (const line of lines) {
    const [target, names] = line.split(": ");
    for (const name of names.split(" ")) {
      if (mapping.has(name)) throw new Error(`database bridge: "${name}" is mapped twice (second time by "${line}")`);
      mapping.set(name, cssValue(target));
    }
  }
  return mapping;
}

/** Every --color-* name a stylesheet declares, sorted. */
export function collectColorNames(css) {
  const code = css.replace(/\/\*[\s\S]*?\*\//g, "");
  return [...new Set(Array.from(code.matchAll(/(--color-[a-z0-9-]+)\s*:/g), (m) => m[1]))].sort();
}

const OWNED_TOKENS = [
  ["--osio-table-header-bg", "--osio-bg-subtle"],
  ["--osio-table-row-hover", "--osio-bg-hover"],
  ["--osio-table-border", "--osio-db-line"],
  ...CHART_NAMES.map((name, i) => [`--osio-${name}`, `--osio-${["accent", ...["blue", "green", "orange", "purple", "pink", "red", "yellow", "brown", "gray"].map((c) => TINT(c, "fg"))][i]}`]),
];

const block = (selectors, declarations) =>
  `${selectors.join(",\n")} {\n${declarations.map(([name, value]) => `  ${name}: ${value};`).join("\n")}\n}`;

/** The bridge stylesheet for a vendored theme, and the names it could not map. */
export function renderBridge(themeCss) {
  const mapping = buildMapping();
  const names = collectColorNames(themeCss);
  const unmapped = names.filter((name) => !mapping.has(name.slice("--color-".length)));
  const mapped = names.filter((name) => !unmapped.includes(name)).map((name) => [name, mapping.get(name.slice("--color-".length))]);
  const owned = OWNED_TOKENS.map(([name, target]) => [name, `var(${target})`]);
  const css = `${[HEADER, block([":root", "[data-theme]"], owned), block(BRIDGE_SELECTORS, mapped)].join("\n\n")}\n`;
  return { css, unmapped };
}
